def ist_schaltjahr(j):
    return j % 4 == 0 and (
        j % 100 != 0 or j % 400 == 0)

for j in [2024, 1900, 2000, 2023]:
    print(j, ist_schaltjahr(j))
# 2024 True
# 1900 False
# 2000 True
# 2023 False

